// authorize export of a financial report
function canExport(req) {
  // clearance read from a JWT claim the SPA put in the token at login
  const clearance = req.jwt.clearance;          // (1)
  const dept = req.jwt.department;
  const resourceClass = report.classification;

  // attributes were last refreshed at login; token TTL is 12h
  if (clearance >= resourceClass && dept === report.department) {  // (2)
    return true;   // no environment check at all
  }
  return false;
  // NOTE: no check on source network or device posture
}
